USE ERPAnalyticsDb;
GO
CREATE TABLE Aziende(AziendaId INT IDENTITY PRIMARY KEY,Codice CHAR(5) UNIQUE NOT NULL,RagioneSociale NVARCHAR(150) NOT NULL,PartitaIVA CHAR(11) UNIQUE NOT NULL,Provincia CHAR(2),Settore NVARCHAR(80),FatturatoAnnuale DECIMAL(18,2));
CREATE TABLE Sedi(SedeId INT IDENTITY PRIMARY KEY,AziendaId INT NOT NULL,Descrizione NVARCHAR(100),Indirizzo NVARCHAR(150),CAP CHAR(5),Comune NVARCHAR(80),Provincia CHAR(2),FOREIGN KEY(AziendaId) REFERENCES Aziende(AziendaId));
CREATE TABLE Reparti(RepartoId INT IDENTITY PRIMARY KEY,AziendaId INT NOT NULL,Codice VARCHAR(20) UNIQUE,Nome NVARCHAR(100),FOREIGN KEY(AziendaId) REFERENCES Aziende(AziendaId));
CREATE TABLE CentriCosto(CentroCostoId INT IDENTITY PRIMARY KEY,AziendaId INT NOT NULL,Codice VARCHAR(20) UNIQUE,Descrizione NVARCHAR(120),RepartoId INT,FOREIGN KEY(AziendaId) REFERENCES Aziende(AziendaId),FOREIGN KEY(RepartoId) REFERENCES Reparti(RepartoId));
CREATE TABLE Dipendenti(DipendenteId INT IDENTITY PRIMARY KEY,AziendaId INT NOT NULL,RepartoId INT,Nome NVARCHAR(60),Cognome NVARCHAR(60),Email NVARCHAR(150),DataAssunzione DATE,Qualifica NVARCHAR(100),CostoOrario DECIMAL(10,2),FOREIGN KEY(AziendaId) REFERENCES Aziende(AziendaId),FOREIGN KEY(RepartoId) REFERENCES Reparti(RepartoId));
CREATE TABLE Agenti(AgenteId INT IDENTITY PRIMARY KEY,AziendaId INT NOT NULL,Codice VARCHAR(20) UNIQUE,Nome NVARCHAR(60),Cognome NVARCHAR(60),Zona NVARCHAR(60),PercentualeProvvigione DECIMAL(5,2),FOREIGN KEY(AziendaId) REFERENCES Aziende(AziendaId));
CREATE TABLE Clienti(ClienteId INT IDENTITY PRIMARY KEY,AziendaId INT NOT NULL,Codice VARCHAR(20) UNIQUE,RagioneSociale NVARCHAR(150),PartitaIVA CHAR(11),Citta NVARCHAR(80),Provincia CHAR(2),Segmento NVARCHAR(40),Fido DECIMAL(14,2),AgenteId INT,FOREIGN KEY(AziendaId) REFERENCES Aziende(AziendaId),FOREIGN KEY(AgenteId) REFERENCES Agenti(AgenteId));
CREATE TABLE Fornitori(FornitoreId INT IDENTITY PRIMARY KEY,AziendaId INT NOT NULL,Codice VARCHAR(20) UNIQUE,RagioneSociale NVARCHAR(150),PartitaIVA CHAR(11),Citta NVARCHAR(80),Provincia CHAR(2),Categoria NVARCHAR(60),Fido DECIMAL(14,2),FOREIGN KEY(AziendaId) REFERENCES Aziende(AziendaId));
CREATE TABLE Vettori(VettoreId INT IDENTITY PRIMARY KEY,AziendaId INT NOT NULL,Codice VARCHAR(20) UNIQUE,RagioneSociale NVARCHAR(150),Provincia CHAR(2),CostoMedioSpedizione DECIMAL(10,2),FOREIGN KEY(AziendaId) REFERENCES Aziende(AziendaId));
CREATE TABLE Banche(BancaId INT IDENTITY PRIMARY KEY,AziendaId INT NOT NULL,CodiceABI CHAR(5),Nome NVARCHAR(100),Provincia CHAR(2),FOREIGN KEY(AziendaId) REFERENCES Aziende(AziendaId));
CREATE TABLE CategorieArticolo(CategoriaId INT IDENTITY PRIMARY KEY,Codice VARCHAR(20) UNIQUE,Descrizione NVARCHAR(100),Famiglia NVARCHAR(80));
CREATE TABLE UnitaMisura(UnitaMisuraId INT IDENTITY PRIMARY KEY,Codice CHAR(5) UNIQUE,Descrizione NVARCHAR(50),FattoreConversione DECIMAL(12,4));
CREATE TABLE Articoli(ArticoloId INT IDENTITY PRIMARY KEY,Codice VARCHAR(30) UNIQUE,Descrizione NVARCHAR(150),CategoriaId INT,UnitaMisuraId INT,CostoStandard DECIMAL(14,2),PrezzoVendita DECIMAL(14,2),PesoKg DECIMAL(10,3),TipoArticolo VARCHAR(20),ScortaMinima DECIMAL(12,2),FOREIGN KEY(CategoriaId) REFERENCES CategorieArticolo(CategoriaId),FOREIGN KEY(UnitaMisuraId) REFERENCES UnitaMisura(UnitaMisuraId));
CREATE TABLE Magazzini(MagazzinoId INT IDENTITY PRIMARY KEY,AziendaId INT NOT NULL,Codice VARCHAR(20) UNIQUE,Descrizione NVARCHAR(100),Comune NVARCHAR(80),Provincia CHAR(2),FOREIGN KEY(AziendaId) REFERENCES Aziende(AziendaId));
CREATE TABLE Ubicazioni(UbicazioneId INT IDENTITY PRIMARY KEY,MagazzinoId INT NOT NULL,Codice VARCHAR(30) UNIQUE,Corsia VARCHAR(10),Scaffale VARCHAR(10),Piano INT,FOREIGN KEY(MagazzinoId) REFERENCES Magazzini(MagazzinoId));
CREATE TABLE Listini(ListinoId INT IDENTITY PRIMARY KEY,Codice VARCHAR(20) UNIQUE,Descrizione NVARCHAR(100),Valuta CHAR(3),DataValiditaDal DATE,DataValiditaAl DATE);
CREATE TABLE ListiniRighe(ListinoRigaId INT IDENTITY PRIMARY KEY,ListinoId INT NOT NULL,ArticoloId INT NOT NULL,Prezzo DECIMAL(14,2),ScontoPercentuale DECIMAL(5,2),QuantitaMinima DECIMAL(12,2),FOREIGN KEY(ListinoId) REFERENCES Listini(ListinoId),FOREIGN KEY(ArticoloId) REFERENCES Articoli(ArticoloId));
CREATE TABLE CondizioniPagamento(CondizionePagamentoId INT IDENTITY PRIMARY KEY,Codice VARCHAR(20) UNIQUE,Descrizione NVARCHAR(100),GiorniScadenza INT,NumeroRate INT);
CREATE TABLE AliquoteIVA(AliquotaIVAId INT IDENTITY PRIMARY KEY,Codice VARCHAR(10) UNIQUE,Descrizione NVARCHAR(80),Percentuale DECIMAL(5,2));
CREATE TABLE CausaliMagazzino(CausaleId INT IDENTITY PRIMARY KEY,Codice VARCHAR(20) UNIQUE,Descrizione NVARCHAR(100),Segno SMALLINT);
CREATE TABLE MovimentiMagazzino(MovimentoId INT IDENTITY PRIMARY KEY,DataMovimento DATE,ArticoloId INT,MagazzinoId INT,UbicazioneId INT,CausaleId INT,Quantita DECIMAL(14,3),CostoUnitario DECIMAL(14,2),Documento VARCHAR(40),FOREIGN KEY(ArticoloId) REFERENCES Articoli(ArticoloId),FOREIGN KEY(MagazzinoId) REFERENCES Magazzini(MagazzinoId),FOREIGN KEY(UbicazioneId) REFERENCES Ubicazioni(UbicazioneId),FOREIGN KEY(CausaleId) REFERENCES CausaliMagazzino(CausaleId));
CREATE TABLE Lotti(LottoId INT IDENTITY PRIMARY KEY,CodiceLotto VARCHAR(40) UNIQUE,ArticoloId INT,DataProduzione DATE,DataScadenza DATE,Quantita DECIMAL(14,3),FOREIGN KEY(ArticoloId) REFERENCES Articoli(ArticoloId));
CREATE TABLE Seriali(SerialeId INT IDENTITY PRIMARY KEY,CodiceSeriale VARCHAR(60) UNIQUE,ArticoloId INT,Stato VARCHAR(30),DataCarico DATE,FOREIGN KEY(ArticoloId) REFERENCES Articoli(ArticoloId));
CREATE TABLE OrdiniClienti(OrdineClienteId INT IDENTITY PRIMARY KEY,NumeroOrdine VARCHAR(30) UNIQUE,DataOrdine DATE,ClienteId INT,AgenteId INT,Stato VARCHAR(30),TotaleNetto DECIMAL(16,2),TotaleIVA DECIMAL(16,2),TotaleDocumento DECIMAL(16,2),FOREIGN KEY(ClienteId) REFERENCES Clienti(ClienteId),FOREIGN KEY(AgenteId) REFERENCES Agenti(AgenteId));
CREATE TABLE RigheOrdineCliente(RigaOrdineClienteId INT IDENTITY PRIMARY KEY,OrdineClienteId INT,NumeroRiga INT,ArticoloId INT,Quantita DECIMAL(14,3),PrezzoUnitario DECIMAL(14,2),ScontoPercentuale DECIMAL(5,2),ImportoNetto DECIMAL(16,2),FOREIGN KEY(OrdineClienteId) REFERENCES OrdiniClienti(OrdineClienteId),FOREIGN KEY(ArticoloId) REFERENCES Articoli(ArticoloId));
CREATE TABLE DDTClienti(DDTClienteId INT IDENTITY PRIMARY KEY,NumeroDDT VARCHAR(30) UNIQUE,DataDDT DATE,ClienteId INT,OrdineClienteId INT,VettoreId INT,TotaleQuantita DECIMAL(14,3),FOREIGN KEY(ClienteId) REFERENCES Clienti(ClienteId),FOREIGN KEY(OrdineClienteId) REFERENCES OrdiniClienti(OrdineClienteId),FOREIGN KEY(VettoreId) REFERENCES Vettori(VettoreId));
CREATE TABLE RigheDDTCliente(RigaDDTClienteId INT IDENTITY PRIMARY KEY,DDTClienteId INT,ArticoloId INT,Quantita DECIMAL(14,3),FOREIGN KEY(DDTClienteId) REFERENCES DDTClienti(DDTClienteId),FOREIGN KEY(ArticoloId) REFERENCES Articoli(ArticoloId));
CREATE TABLE FattureClienti(FatturaClienteId INT IDENTITY PRIMARY KEY,NumeroFattura VARCHAR(30) UNIQUE,DataFattura DATE,ClienteId INT,OrdineClienteId INT,Imponibile DECIMAL(16,2),IVA DECIMAL(16,2),Totale DECIMAL(16,2),Stato VARCHAR(30),FOREIGN KEY(ClienteId) REFERENCES Clienti(ClienteId),FOREIGN KEY(OrdineClienteId) REFERENCES OrdiniClienti(OrdineClienteId));
CREATE TABLE RigheFatturaCliente(RigaFatturaClienteId INT IDENTITY PRIMARY KEY,FatturaClienteId INT,ArticoloId INT,AliquotaIVAId INT,Quantita DECIMAL(14,3),PrezzoUnitario DECIMAL(14,2),ScontoPercentuale DECIMAL(5,2),Imponibile DECIMAL(16,2),FOREIGN KEY(FatturaClienteId) REFERENCES FattureClienti(FatturaClienteId),FOREIGN KEY(ArticoloId) REFERENCES Articoli(ArticoloId),FOREIGN KEY(AliquotaIVAId) REFERENCES AliquoteIVA(AliquotaIVAId));
CREATE TABLE OrdiniFornitori(OrdineFornitoreId INT IDENTITY PRIMARY KEY,NumeroOrdine VARCHAR(30) UNIQUE,DataOrdine DATE,FornitoreId INT,Stato VARCHAR(30),TotaleNetto DECIMAL(16,2),TotaleIVA DECIMAL(16,2),TotaleDocumento DECIMAL(16,2),FOREIGN KEY(FornitoreId) REFERENCES Fornitori(FornitoreId));
CREATE TABLE RigheOrdineFornitore(RigaOrdineFornitoreId INT IDENTITY PRIMARY KEY,OrdineFornitoreId INT,ArticoloId INT,Quantita DECIMAL(14,3),PrezzoUnitario DECIMAL(14,2),ImportoNetto DECIMAL(16,2),FOREIGN KEY(OrdineFornitoreId) REFERENCES OrdiniFornitori(OrdineFornitoreId),FOREIGN KEY(ArticoloId) REFERENCES Articoli(ArticoloId));
CREATE TABLE DDTFornitori(DDTFornitoreId INT IDENTITY PRIMARY KEY,NumeroDDT VARCHAR(30) UNIQUE,DataDDT DATE,FornitoreId INT,OrdineFornitoreId INT,VettoreId INT,TotaleQuantita DECIMAL(14,3),FOREIGN KEY(FornitoreId) REFERENCES Fornitori(FornitoreId),FOREIGN KEY(OrdineFornitoreId) REFERENCES OrdiniFornitori(OrdineFornitoreId),FOREIGN KEY(VettoreId) REFERENCES Vettori(VettoreId));
CREATE TABLE RigheDDTFornitore(RigaDDTFornitoreId INT IDENTITY PRIMARY KEY,DDTFornitoreId INT,ArticoloId INT,Quantita DECIMAL(14,3),FOREIGN KEY(DDTFornitoreId) REFERENCES DDTFornitori(DDTFornitoreId),FOREIGN KEY(ArticoloId) REFERENCES Articoli(ArticoloId));
CREATE TABLE FattureFornitori(FatturaFornitoreId INT IDENTITY PRIMARY KEY,NumeroFattura VARCHAR(30) UNIQUE,DataFattura DATE,FornitoreId INT,Imponibile DECIMAL(16,2),IVA DECIMAL(16,2),Totale DECIMAL(16,2),Stato VARCHAR(30),FOREIGN KEY(FornitoreId) REFERENCES Fornitori(FornitoreId));
CREATE TABLE RigheFatturaFornitore(RigaFatturaFornitoreId INT IDENTITY PRIMARY KEY,FatturaFornitoreId INT,ArticoloId INT,AliquotaIVAId INT,Quantita DECIMAL(14,3),PrezzoUnitario DECIMAL(14,2),Imponibile DECIMAL(16,2),FOREIGN KEY(FatturaFornitoreId) REFERENCES FattureFornitori(FatturaFornitoreId),FOREIGN KEY(ArticoloId) REFERENCES Articoli(ArticoloId),FOREIGN KEY(AliquotaIVAId) REFERENCES AliquoteIVA(AliquotaIVAId));
CREATE TABLE DistinteBase(DistintaBaseId INT IDENTITY PRIMARY KEY,Codice VARCHAR(30) UNIQUE,ArticoloPadreId INT,Revisione VARCHAR(10),DataValidita DATE,Stato VARCHAR(20),FOREIGN KEY(ArticoloPadreId) REFERENCES Articoli(ArticoloId));
CREATE TABLE DistinteBaseRighe(DistintaBaseRigaId INT IDENTITY PRIMARY KEY,DistintaBaseId INT,ArticoloComponenteId INT,Quantita DECIMAL(14,4),ScartoPercentuale DECIMAL(5,2),FOREIGN KEY(DistintaBaseId) REFERENCES DistinteBase(DistintaBaseId),FOREIGN KEY(ArticoloComponenteId) REFERENCES Articoli(ArticoloId));
CREATE TABLE CicliProduzione(CicloId INT IDENTITY PRIMARY KEY,Codice VARCHAR(30) UNIQUE,ArticoloId INT,Revisione VARCHAR(10),TempoAttrezzaggioMin INT,TempoCicloMin DECIMAL(10,2),FOREIGN KEY(ArticoloId) REFERENCES Articoli(ArticoloId));
CREATE TABLE FasiCiclo(FaseCicloId INT IDENTITY PRIMARY KEY,CicloId INT,FaseNumero INT,Descrizione NVARCHAR(120),RepartoId INT,CentroCostoId INT,TempoStandardMin DECIMAL(10,2),FOREIGN KEY(CicloId) REFERENCES CicliProduzione(CicloId),FOREIGN KEY(RepartoId) REFERENCES Reparti(RepartoId),FOREIGN KEY(CentroCostoId) REFERENCES CentriCosto(CentroCostoId));
CREATE TABLE OrdiniProduzione(OrdineProduzioneId INT IDENTITY PRIMARY KEY,NumeroOrdine VARCHAR(30) UNIQUE,ArticoloId INT,QuantitaPrevista DECIMAL(14,3),DataInizio DATE,DataFinePrevista DATE,Stato VARCHAR(30),FOREIGN KEY(ArticoloId) REFERENCES Articoli(ArticoloId));
CREATE TABLE AvanzamentiProduzione(AvanzamentoId INT IDENTITY PRIMARY KEY,OrdineProduzioneId INT,FaseNumero INT,DataRilevazione DATETIME2,DipendenteId INT,QuantitaBuona DECIMAL(14,3),QuantitaScarto DECIMAL(14,3),TempoMinuti DECIMAL(10,2),FOREIGN KEY(OrdineProduzioneId) REFERENCES OrdiniProduzione(OrdineProduzioneId),FOREIGN KEY(DipendenteId) REFERENCES Dipendenti(DipendenteId));
CREATE TABLE ControlliQualita(ControlloQualitaId INT IDENTITY PRIMARY KEY,OrdineProduzioneId INT,ArticoloId INT,DataControllo DATE,TipoControllo VARCHAR(50),Esito VARCHAR(20),ValoreMisurato DECIMAL(12,3),ValoreTarget DECIMAL(12,3),FOREIGN KEY(OrdineProduzioneId) REFERENCES OrdiniProduzione(OrdineProduzioneId),FOREIGN KEY(ArticoloId) REFERENCES Articoli(ArticoloId));
CREATE TABLE NonConformita(NonConformitaId INT IDENTITY PRIMARY KEY,ControlloQualitaId INT,Codice VARCHAR(30) UNIQUE,DataApertura DATE,Gravita VARCHAR(20),Causa NVARCHAR(150),CostoStimato DECIMAL(14,2),Stato VARCHAR(30),FOREIGN KEY(ControlloQualitaId) REFERENCES ControlliQualita(ControlloQualitaId));
CREATE TABLE ContiContabili(ContoId INT IDENTITY PRIMARY KEY,Codice VARCHAR(20) UNIQUE,Descrizione NVARCHAR(120),TipoConto VARCHAR(30),ClasseBilancio VARCHAR(30));
CREATE TABLE MovimentiContabili(MovimentoContabileId INT IDENTITY PRIMARY KEY,DataRegistrazione DATE,ContoDareId INT,ContoAvereId INT,Documento VARCHAR(40),Descrizione NVARCHAR(200),Importo DECIMAL(16,2),CentroCostoId INT,FOREIGN KEY(ContoDareId) REFERENCES ContiContabili(ContoId),FOREIGN KEY(ContoAvereId) REFERENCES ContiContabili(ContoId),FOREIGN KEY(CentroCostoId) REFERENCES CentriCosto(CentroCostoId));
CREATE TABLE Scadenze(ScadenzaId INT IDENTITY PRIMARY KEY,Tipo VARCHAR(20),Documento VARCHAR(40),ControparteId INT,DataScadenza DATE,Importo DECIMAL(16,2),Stato VARCHAR(20));
CREATE TABLE IncassiPagamenti(IncassoPagamentoId INT IDENTITY PRIMARY KEY,Tipo VARCHAR(20),Documento VARCHAR(40),DataOperazione DATE,Importo DECIMAL(16,2),BancaId INT,ScadenzaId INT,FOREIGN KEY(BancaId) REFERENCES Banche(BancaId),FOREIGN KEY(ScadenzaId) REFERENCES Scadenze(ScadenzaId));
CREATE TABLE Commesse(CommessaId INT IDENTITY PRIMARY KEY,Codice VARCHAR(30) UNIQUE,Descrizione NVARCHAR(150),ClienteId INT,DataApertura DATE,DataChiusura DATE,Budget DECIMAL(16,2),Stato VARCHAR(30),FOREIGN KEY(ClienteId) REFERENCES Clienti(ClienteId));
CREATE TABLE AttivitaCommessa(AttivitaCommessaId INT IDENTITY PRIMARY KEY,CommessaId INT,DipendenteId INT,DataAttivita DATE,Descrizione NVARCHAR(200),Ore DECIMAL(8,2),CostoOrario DECIMAL(10,2),FOREIGN KEY(CommessaId) REFERENCES Commesse(CommessaId),FOREIGN KEY(DipendenteId) REFERENCES Dipendenti(DipendenteId));
CREATE TABLE OpportunitaCRM(OpportunitaId INT IDENTITY PRIMARY KEY,Codice VARCHAR(30) UNIQUE,ClienteId INT,AgenteId INT,DataApertura DATE,Fase VARCHAR(40),ValoreStimato DECIMAL(16,2),Probabilita DECIMAL(5,2),FOREIGN KEY(ClienteId) REFERENCES Clienti(ClienteId),FOREIGN KEY(AgenteId) REFERENCES Agenti(AgenteId));
CREATE TABLE InterazioniCRM(InterazioneId INT IDENTITY PRIMARY KEY,OpportunitaId INT,DataInterazione DATE,Tipo VARCHAR(40),Oggetto NVARCHAR(150),Esito NVARCHAR(150),DipendenteId INT,FOREIGN KEY(OpportunitaId) REFERENCES OpportunitaCRM(OpportunitaId),FOREIGN KEY(DipendenteId) REFERENCES Dipendenti(DipendenteId));
CREATE TABLE Budget(BudgetId INT IDENTITY PRIMARY KEY,Codice VARCHAR(30) UNIQUE,Anno INT,Descrizione NVARCHAR(150),Stato VARCHAR(20));
CREATE TABLE BudgetRighe(BudgetRigaId INT IDENTITY PRIMARY KEY,BudgetId INT,CentroCostoId INT,ContoId INT,Mese INT,ImportoBudget DECIMAL(16,2),ImportoConsuntivo DECIMAL(16,2),FOREIGN KEY(BudgetId) REFERENCES Budget(BudgetId),FOREIGN KEY(CentroCostoId) REFERENCES CentriCosto(CentroCostoId),FOREIGN KEY(ContoId) REFERENCES ContiContabili(ContoId));
CREATE TABLE AuditLog(AuditId BIGINT IDENTITY PRIMARY KEY,DataOra DATETIME2 NOT NULL DEFAULT SYSDATETIME(),Utente NVARCHAR(100),Azione VARCHAR(20),TabellaNome SYSNAME,RecordId INT,ValorePrecedente NVARCHAR(500),ValoreNuovo NVARCHAR(500));
